/* jd_emblem.h — the JellyDazzle mark as a 160x160 luminance MASK.
 *
 * Generated from assets/brand/emblem.png, then treated so it can never read as
 * a pasted picture:
 *   - thresholded, so only the bright mark survives and the dark tech
 *     background falls away entirely;
 *   - radially vignetted, so the 160x160 SQUARE BOUNDARY fades to nothing.
 *     Without this the mask's own bounding box is visible as a hard rotated
 *     square, which is exactly the sticker look we are avoiding.
 *
 * These are not colours. They select palette indices, so the mark is made of
 * whatever the engine is already painting.
 */
